(()=>{'use strict';const $=id=>document.getElementById(id);if(!$('apkUploadForm'))return;
const base=window.ELVANOQ_CONFIG.downloadService;let busy=false,controller=null,uploadId=null,activeXHR=null;
const say=(text,ok=false)=>{const el=$('apkUploadMessage');el.hidden=!text;el.textContent=text;el.classList.toggle('success',ok);};
const node=(tag,text)=>{const el=document.createElement(tag);el.textContent=text;return el;};
async function access(){if(!window.ELVANOQ_ADMIN_ACCESS)throw new Error('Entre no painel como administrador.');return window.ELVANOQ_ADMIN_ACCESS.token();}
async function api(path,body,signal){const t=await access(),r=await fetch(base+path,{method:body===undefined?'GET':'POST',headers:{Authorization:'Bearer '+t,'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),signal:signal||AbortSignal.timeout(120000),cache:'no-store'});const d=await r.json();if(!r.ok)throw new Error(d.message||'Não foi possível concluir.');return d;}
function notesEditor(card,r){const edit=node('button','Editar notas / novidades');edit.type='button';edit.addEventListener('click',()=>{edit.disabled=true;const form=node('form','');form.className='apk-upload-form';const label=node('label','Novidades da versão '+r.version),input=node('textarea','');input.id='apkEditNotes-'+r.id;label.htmlFor=input.id;input.rows=4;input.maxLength=2000;input.value=r.notes||'';const save=node('button','Salvar notas'),cancel=node('button','Cancelar'),message=node('p','');save.type='submit';cancel.type='button';message.setAttribute('role','status');cancel.addEventListener('click',()=>{form.remove();edit.disabled=false;});form.addEventListener('submit',async e=>{e.preventDefault();save.disabled=cancel.disabled=true;try{await api('/admin/releases/'+r.id+'/notes',{notes:input.value});say('Novidades da versão '+r.version+' atualizadas.',true);await load(true);}catch(e){message.textContent=e.message;save.disabled=cancel.disabled=false;}});form.append(label,input,save,cancel,message);card.append(form);input.focus();});card.append(edit);}
function deleteOption(card,r){const button=node('button','Excluir arquivo');button.type='button';button.className='danger-button';button.addEventListener('click',()=>{button.disabled=true;const review=node('div','');review.className='message';review.setAttribute('role','alert');review.append(node('p','Excluir permanentemente o APK da versão '+r.version+' ('+(r.size/1048576).toFixed(1)+' MB)? O arquivo será removido do armazenamento e não poderá ser restaurado. O APK disponível para download será mantido.'));const yes=node('button','Confirmar exclusão'),no=node('button','Cancelar');yes.type=no.type='button';yes.className='danger-button';yes.addEventListener('click',async()=>{yes.disabled=no.disabled=true;try{await api('/admin/releases/'+r.id+'/delete',{confirm:true});say('APK da versão '+r.version+' excluído do armazenamento.',true);await load(true);}catch(e){say(e.message);yes.disabled=no.disabled=false;}});no.addEventListener('click',()=>{review.remove();button.disabled=false;});review.append(yes,no);card.append(review);no.focus();});card.append(button);}
let loading=null,lastLoaded=0;
function load(force=false){if(busy)return Promise.resolve();if(loading)return force?loading.then(()=>load(true)):loading;if(!force&&Date.now()-lastLoaded<30000)return Promise.resolve();loading=loadReleases().finally(()=>{loading=null;});return loading;}
async function loadReleases(){try{const d=await api('/admin/releases');$('apkCurrent').textContent=d.current?'Versão disponível: '+d.current.version+' · '+(d.current.size/1048576).toFixed(1)+' MB · '+d.current.download_url:'Nenhum APK hospedado foi disponibilizado. O download anterior permanece no site.';lastLoaded=Date.now();const list=$('apkReleaseList'),bulkFiles=[];list.replaceChildren();if(!d.releases.length)list.append(node('p','Nenhum arquivo enviado ainda.'));for(const r of d.releases){const card=node('article','');card.className='device-card';card.append(node('strong','Versão '+r.version),node('small',(r.size/1048576).toFixed(1)+' MB · Enviado em '+new Date(r.created_at).toLocaleString('pt-BR')),node('small','SHA-256: '+r.sha256));if(r.notes){const notes=node('p',r.notes);notes.style.whiteSpace='pre-wrap';card.append(notes);}notesEditor(card,r);if(d.current?.id===r.id)card.append(node('strong','Disponível para download'));else{const button=node('button',r.published_at?'Restaurar esta versão':'Disponibilizar esta versão');button.type='button';button.addEventListener('click',()=>{button.disabled=true;const review=node('div','');review.className='message';review.append(node('p','Disponibilizar a versão '+r.version+'? O endereço de download passará a entregar este arquivo. Confira a versão e a assinatura antes de continuar.'));const yes=node('button','Confirmar versão '+r.version),no=node('button','Cancelar');yes.type=no.type='button';yes.addEventListener('click',async()=>{yes.disabled=true;try{await api('/admin/releases/'+r.id+'/publish',{});say('Versão '+r.version+' disponível no endereço fixo de download.',true);await load(true);}catch(e){say(e.message);yes.disabled=false;}});no.addEventListener('click',()=>{review.remove();button.disabled=false;});review.append(yes,no);card.append(review);});card.append(button);deleteOption(card,r);bulkFiles.push({row:card,name:'Versão '+r.version,id:r.id});}list.append(card);}window.ELVANOQ_BULK?.mount(list,bulkFiles,[{title:'Excluir APKs antigos',eligible:()=>true,destructive:true,warning:'Os arquivos selecionados serão removidos definitivamente. A versão disponível para download fica protegida.',run:entry=>api('/admin/releases/'+entry.id+'/delete',{confirm:true})}],()=>load(true));window.ELVANOQ_PAGES?.render();}catch(e){$('apkCurrent').textContent=e.message;}}
async function part(id,n,blob,start,total,signal){const t=await access();return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();activeXHR=xhr;xhr.open('PUT',base+'/admin/uploads/'+id+'/part?number='+n);xhr.setRequestHeader('Authorization','Bearer '+t);xhr.timeout=120000;xhr.upload.onprogress=e=>{if(e.lengthComputable)$('apkProgress').value=Math.min(97,((start+e.loaded)/total)*97);};xhr.onload=()=>{signal.removeEventListener('abort',abort);activeXHR=null;try{const d=JSON.parse(xhr.responseText);if(xhr.status<200||xhr.status>=300)throw new Error(d.message||'Falha no envio.');resolve(d);}catch(e){reject(e);}};xhr.onerror=()=>reject(new Error('Falha de conexão no envio.'));xhr.ontimeout=()=>reject(new Error('O envio demorou. Tente novamente.'));xhr.onabort=()=>reject(new DOMException('Envio cancelado.','AbortError'));const abort=()=>xhr.abort();signal.addEventListener('abort',abort,{once:true});if(signal.aborted){xhr.abort();return;}xhr.send(blob);});}
$('apkUploadForm').addEventListener('submit',async e=>{e.preventDefault();if(busy)return;const file=$('apkFile').files[0],version=$('apkVersion').value.trim();if(!file||!file.name.toLowerCase().endsWith('.apk')||file.size>200*1048576){say('Escolha um arquivo APK de até 200 MB.');return;}busy=true;controller=new AbortController();$('apkUploadButton').disabled=true;$('apkCancel').hidden=false;$('apkProgress').hidden=false;$('apkProgress').value=0;say('Preparando o envio…');try{const start=await api('/admin/uploads',{version,filename:file.name,size:file.size,notes:$('apkNotes').value},controller.signal);uploadId=start.id;const parts=[];for(let offset=0;offset<file.size;offset+=start.chunk_size){say('Enviando o APK… '+Math.round(offset/file.size*100)+'%');parts.push(await part(start.id,parts.length+1,file.slice(offset,offset+start.chunk_size),offset,file.size,controller.signal));}say('Conferindo estrutura e SHA-256 no servidor…');await api('/admin/uploads/'+start.id+'/complete',{parts},controller.signal);$('apkProgress').value=100;say('APK validado e disponibilizado. O link de download já entrega esta versão.',true);$('apkUploadForm').reset();}catch(e){say(e.name==='AbortError'?'Envio cancelado. A versão disponível não foi alterada.':e.message);}finally{busy=false;activeXHR=null;$('apkUploadButton').disabled=false;$('apkCancel').hidden=true;uploadId=null;await load(true);}});
$('apkCancel').addEventListener('click',()=>{const id=uploadId;controller?.abort();activeXHR?.abort();if(id)api('/admin/uploads/'+id+'/abort',{}).catch(()=>{});});
$('apkRefresh').addEventListener('click',()=>load(true));window.addEventListener('hashchange',()=>{if(location.hash==='#apk')load();});if(location.hash==='#apk')load();
})();
